mapper.select:
SELECT member_id, nickname, email, member_role, member_status
FROM member
WHERE member_id = #{memberId}

mapper.update:
UPDATE member
SET member_status = #{memberStatus}
WHERE member_id = #{memberId}

UPDATE member
SET member_role = #{memberRole}
WHERE member_id = #{memberId}

UPDATE board
SET is_hidden = #{hidden}
WHERE board_id = #{boardId}

UPDATE board_comment
SET is_hidden = #{hidden}
WHERE comment_id = #{commentId}

mapper.select:
SELECT COUNT(*)
FROM stock
WHERE stock_code = #{stockCode}
  AND stock_code != #{currentStockCode}

SELECT COUNT(*)
FROM stock
WHERE stock_code = #{stockCode}

mapper.update:
UPDATE stock
SET stock_code = #{stockCode},
    stock_name = #{stockName},
    current_price = #{currentPrice}
WHERE stock_code = #{currentStockCode}

mapper.select:
SELECT COUNT(*)
FROM glossary
WHERE term = #{term}

    AND term_id != #{termId}

mapper.update:
UPDATE glossary
SET term = #{term},
    definition = #{definition},
    category = #{category}
WHERE term_id = #{termId}
